// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1e30);

        // initialize the log file with a real (working) LogFile contract
        LogFile lf = new LogFile();
        vm.prank(actor);
        c.SetLogFile(address(lf));

        // deposit through the public entry; the reference logs via the stored Log
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // RULE: with a valid LogFile configured, any Deposit must succeed.
        // The mutant never sets Log, so Log.AddMessage targets address(0) and reverts.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0));
        c.SetLogFile(logAddr);
        assertTrue(c.Log() == logAddr);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint _val) public
    {
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _val));
        require(ok);
        assert(c.MinSum() == _val);
    }

    receive() external payable {}
    fallback() external payable {}
}
